"""RPC Book Two, Titles One to Three (Arts. 114-160): national security, fundamental laws, public order."""

RA9346 = {'t': 'RA 9346 (2006)', 's': 'Prohibits the imposition of the death penalty; reclusion perpetua is imposed instead, without eligibility for parole.', 'u': '#/code/ra9346'}
PD532 = {'t': 'PD 532 (1974), the Anti-Piracy and Anti-Highway Robbery Law', 's': 'Punishes piracy in Philippine waters (including by passengers or crew) and highway robbery; it coexists with Arts. 122-123.', 'u': ''}
HSA = {'t': 'RA 11479 (2020), the Anti-Terrorism Act', 's': 'Terrorism and related acts are punished separately; rebellion and coup d’état remain under the Code.', 'u': '#/code/ra11479'}


def add(n):
    # ------------------------------------------------------------ Title One: national security and the law of nations
    n(114, 'Treason is committed by a Filipino citizen who, in time of war, levies war against the Philippines or adheres to her enemies by giving them aid or comfort, here or abroad. A resident alien who does the same is also liable. Conviction requires two witnesses to the same overt act, or a confession in open court.',
      k=['Offender: a Filipino citizen (or a resident alien, par. 2) owing allegiance.', 'There is a war in which the Philippines is involved.', 'Two modes: (1) levying war against the Government; or (2) adhering to the enemy, giving aid or comfort.', 'Adherence (the intent) and aid or comfort (the overt act) must concur.'],
      t=['The two-witness rule applies to adherence by overt act; a confession counts only if made in open court.', 'Treason is a continuing crime: many overt acts make one treason.', 'Treason cannot be complexed with murder or other crimes committed as overt acts of it; they are absorbed.', 'Death in the text is now reclusion perpetua without parole (RA 9346).'],
      d=[{'n': 'Laurel v. Misa', 'c': '77 Phil. 856 (1947)', 'h': 'The absolute allegiance of a citizen to his sovereign is not suspended during enemy occupation; collaborators who aided the Japanese could be convicted of treason.', 'r': 'Allegiance during occupation.'}],
      i=[RA9346], chk=['two (2) witnesses', 'open court', 'aid or comfort'])
    n(115, 'Conspiracy and proposal to commit treason are punished — an exception to the rule that conspiracy and proposal are punished only when the law says so (Art. 8).',
      t=['The penalty is lighter than for treason itself; once treason is committed, conspiracy is only a mode of incurring liability.'], chk=['conspiracy or proposal'])
    n(116, 'Misprision of treason: a person owing allegiance, who is not a foreigner, knows of a conspiracy against the Government and does not disclose it as soon as possible to the governor or fiscal of the province, or the mayor or fiscal of the city. He is punished as an accessory to treason.',
      t=['Only citizens can commit it (“without being a foreigner”).', 'It is a crime of omission; the conspiracy must be to commit treason.', 'Though “punished as an accessory”, the offender is a principal of misprision; the penalty is the one for accessories.'],
      chk=['without being a foreigner', 'accessory to the crime of treason'])
    n(117, 'Espionage under the Code: (1) entering, without authority, a warship, fort or military establishment to obtain confidential defense information; or (2) a public officer who, having such information by reason of office, discloses it to a foreign representative.',
      t=['Unlike treason, espionage may be committed in peace or war and by a non-citizen. CA 616 (1941) separately punishes espionage and related acts.'], chk=['warship, fort or naval or military establishment'])
    n(118, 'Inciting to war or giving motives for reprisals: a public officer or private individual who, by unlawful or unauthorized acts, provokes or gives occasion for a war involving the Philippines, or exposes Filipinos to reprisals.',
      t=['Intent to provoke war is not required; it is enough that the acts provoke or give occasion for it.'], chk=['reprisals'])
    n(119, 'Violation of neutrality: in a war in which the Philippines is not involved, violating a regulation issued by competent authority to enforce neutrality.', chk=['neutrality'])
    n(120, 'Correspondence with a hostile country in time of war: punished more heavily if the correspondence is prohibited, carried on in ciphers, or gives information useful to the enemy; the heaviest when the offender intends to aid the enemy.', chk=['ciphers or conventional signs'])
    n(121, 'Flight to an enemy country: a person owing allegiance who attempts to flee or go to an enemy country when prohibited by competent authority.', t=['The mere attempt consummates the crime.'], chk=['attempts to flee'])
    n(122, 'Piracy (as amended by RA 7659): attacking or seizing a vessel on the high seas or in Philippine waters, or — by one who is not a member of its complement nor a passenger — seizing its cargo, equipment or passengers. Mutiny on the high seas or in Philippine waters is punished the same way.',
      k=['Piracy: offender is a stranger to the vessel (not crew or passenger).', 'Mutiny: the unlawful resistance to a superior officer, or the raising of commotions on board, by the crew or passengers.'],
      t=['RA 7659 (1993) extended Art. 122 to Philippine waters; PD 532 also punishes piracy in Philippine waters, including by crew or passengers.'],
      d=[{'n': 'People v. Tulin', 'c': 'G.R. No. 111709, August 30, 2001', 'h': 'The hijacking of a vessel in Philippine waters and the siphoning of its cargo was piracy under PD 532; Art. 122 as amended by RA 7659 and PD 532 coexist, and PD 532 also covers persons who are not passengers or crew.', 'r': 'Piracy in Philippine waters.'}],
      i=[PD532], chk=['Philippine waters', 'mutiny'])
    n(123, 'Qualified piracy: piracy or mutiny (Art. 122) committed (1) after seizing the vessel by boarding or firing on it; (2) where the pirates abandoned their victims without means of saving themselves; or (3) accompanied by murder, homicide, physical injuries or rape.',
      t=['It is a special complex crime: murder, homicide, physical injuries or rape are not charged separately.', 'The penalty in the text (reclusion perpetua to death) is reclusion perpetua without parole under RA 9346.'],
      i=[RA9346], chk=['boarding or firing', 'murder, homicide, physical injuries or rape'])

    # ------------------------------------------------------------ Title Two: crimes against the fundamental laws of the State
    n(124, 'Arbitrary detention: a public officer or employee who, without legal grounds, detains a person. The penalty rises with the length of detention (up to three days; more than three up to fifteen; more than fifteen up to six months; more than six months).',
      k=['Offender is a public officer or employee (with authority to detain or order detention).', 'He detains a person.', 'Without legal ground (no crime committed, no violent insanity or ailment requiring confinement).'],
      t=['A private individual who detains another commits illegal detention (Arts. 267-268), not arbitrary detention.', 'Detention need not be in a jail: restraint by intimidation is enough.', 'The legal grounds listed: commission of a crime, and violent insanity or other ailment requiring compulsory confinement in a hospital.'],
      d=[{'n': 'Astorga v. People', 'c': 'G.R. No. 154130, October 1, 2003', 'h': 'A mayor who, with armed men, kept a team of DENR employees from leaving for hours was liable for arbitrary detention; actual physical restraint is not required where the victims were restrained by fear.', 'r': 'Detention without physical confinement.'}],
      chk=['without legal grounds', 'three days', 'fifteen days'])
    n(126, 'Delaying release: a public officer or employee who delays, for the periods in Art. 124, the execution of a judicial or executive order to release a prisoner, or delays serving notice of the order or the proceedings on a petition for release.', chk=['order for the release'])
    n(127, 'Expulsion: a public officer or employee who, without authority of law, expels a person from the Philippines or compels him to change his residence.',
      t=['Only the courts (in criminal cases) and, for aliens, the immigration authorities acting under law may expel or deport.'], chk=['change his residence'])
    n(128, 'Violation of domicile: a public officer or employee who, without a judicial order, (1) enters a dwelling against the will of the owner; (2) searches papers or effects without the owner’s consent; or (3) having entered surreptitiously, refuses to leave when required. Heavier if committed at night or if papers or effects not constituting evidence are not returned.',
      t=['A private person who enters a dwelling against the owner’s will commits trespass to dwelling (Art. 280).', '“Against the will” requires opposition, express or implied; mere absence of consent is not enough for the first mode.'],
      chk=['against the will of the owner'])
    n(129, 'A public officer who procures a search warrant without just cause, or who exceeds his authority or uses unnecessary severity in executing one legally obtained, is punished in addition to any other offense committed.',
      t=['The penalty is “in addition to” liability for other crimes committed (e.g., perjury in the application).'], chk=['without just cause', 'unnecessary severity'])
    n(130, 'Searching a domicile without witnesses: a public officer who, in a lawful search, searches a home, papers or belongings in the absence of the occupant, a family member, or — in their default — two witnesses residing in the same locality.',
      t=['Mirrors Rule 126, Sec. 8 of the Rules of Court; the search must be lawful to begin with (otherwise Art. 128 or 129).'], chk=['two witnesses residing in the same locality'])
    n(131, 'A public officer or employee who, without legal ground, prohibits, interrupts or dissolves a peaceful meeting; hinders a person from joining a lawful association or attending its meetings; or prevents a person from petitioning the authorities for redress of grievances.',
      t=['The offender must be a public officer; a private individual who disturbs a meeting may commit Art. 153 or unjust vexation.', 'Dissolving a meeting that is not peaceful, or that violates a valid permit requirement, is not this crime.'], chk=['peaceful meeting'])
    n(132, 'Interruption of religious worship: a public officer or employee who prevents or disturbs the ceremonies or manifestations of any religion; heavier with violence or threats.', t=['If the offender is a private individual, see Art. 133.'], chk=['ceremonies or manifestations of any religion'])
    n(133, 'Offending religious feelings: anyone who, in a place devoted to religious worship or during a religious ceremony, performs acts notoriously offensive to the feelings of the faithful.',
      k=['Place: devoted to religious worship, or during a religious ceremony.', 'Act: notoriously offensive to the feelings of the faithful (judged from the viewpoint of the faithful).'],
      d=[{'n': 'Celdran v. People', 'c': 'G.R. No. 220127 (Supreme Court, 2018)', 'h': 'A tour guide who entered the Manila Cathedral during an ecumenical service dressed as José Rizal and raised a placard reading “Damaso” was convicted of offending religious feelings; the act was notoriously offensive to the faithful and was done in a place of worship during a ceremony.', 'r': 'Speech and Art. 133.'}],
      chk=['notoriously offensive to the feelings of the faithful'])

    # ------------------------------------------------------------ Title Three: public order
    n(134, 'Rebellion or insurrection: rising and taking arms against the Government to (a) remove from allegiance to it the territory of the Philippines or any part of it, or any body of land, naval or other armed forces; or (b) deprive the Chief Executive or Congress, wholly or partly, of their powers.',
      k=['Element 1: a public uprising and the taking up of arms against the Government.', 'Element 2: the political purpose stated in the article.', 'Rebellion when the object is to overthrow the Government; insurrection when it is to effect some change of minor importance.'],
      t=['Common crimes committed in furtherance of rebellion are absorbed and cannot be complexed with it (People v. Hernandez); crimes for private motives are separate.', 'RA 6968’s text reads “rising and taking arms” (without “publicly”), but the Court continues to require a public uprising.', 'Rebellion is a continuing crime: a rebel may be arrested without a warrant while it continues.'],
      d=[{'n': 'People v. Hernandez', 'c': '99 Phil. 515 (1956)', 'h': 'Murders, arsons and robberies committed as means to or in furtherance of rebellion are absorbed in rebellion; rebellion cannot be complexed with them under Art. 48.', 'r': 'The absorption doctrine.'},
         {'n': 'Enrile v. Salazar', 'c': 'G.R. No. 92163, June 5, 1990', 'h': 'The Court reaffirmed Hernandez: there is no complex crime of rebellion with murder and multiple frustrated murder; the information charged simple rebellion.', 'r': 'Hernandez reaffirmed.'}],
      i=[HSA], chk=['rising and taking arms against the Government', 'Republic of the Philippines'])
    n(136, 'Conspiracy and proposal to commit coup d’état, rebellion or insurrection are punished (as amended by RA 6968 and RA 10951).',
      t=['Mere agreement and decision to rise publicly and take arms is enough for conspiracy; no overt act of rebellion is needed.'], chk=['conspiracy and proposal to commit coup'])
    n(137, 'Disloyalty of public officers or employees: failing to resist a rebellion by all means in their power, continuing to discharge their duties under the control of rebels, or accepting appointment from them.',
      t=['The offender is a public officer or employee who is not in conspiracy with the rebels; if he is, he is a rebel.'], chk=['failed to resist a rebellion'])
    n(138, 'Inciting to rebellion or insurrection: without taking arms or being in open hostility, inciting others to rebel by speeches, proclamations, writings, emblems, banners or other representations.',
      t=['The incitement must be to the acts of rebellion (Art. 134); inciting to sedition is Art. 142.'], chk=['without taking arms or being in open hostility'])
    n(139, 'Sedition: rising publicly and tumultuously to attain, by force, intimidation or other means outside legal methods, any of five objects — preventing the promulgation or execution of a law or the holding of an election; preventing the Government or any public officer from freely exercising functions; inflicting acts of hate or revenge on public officers; committing acts of hate or revenge against private persons or a social class for political or social ends; or despoiling persons or government of property for political or social ends.',
      k=['A public and tumultuous uprising.', 'By force, intimidation or other means outside legal methods.', 'For any of the five objects.'],
      t=['Unlike rebellion, sedition does not require taking up arms and its object is not to overthrow the Government.', '“Tumultuous” means caused by more than three persons who are armed or provided with means of violence (Art. 153).'],
      chk=['rise publicly and tumultuously', 'outside of legal methods'])
    n(140, 'Penalties for sedition: one for the leader, a lower one for other participants.', chk=['leader of sedition'])
    n(141, 'Conspiracy to commit sedition is punished; proposal to commit sedition is not.', t=['A favorite trap: there is no crime of proposal to commit sedition.'], chk=['conspiring to commit the crime of sedition'])
    n(142, 'Inciting to sedition: without taking direct part in sedition, inciting others to its acts by speeches, proclamations, writings, emblems, cartoons, banners or other representations; uttering seditious words or speeches; writing or circulating scurrilous libels against the Government; or knowingly concealing such evil practices.',
      t=['The test is whether the words tend to incite to the acts of sedition, disturb public peace, or lead to rebellion — balanced today against free speech (clear and present danger).'],
      d=[{'n': 'Espuelas v. People', 'c': '90 Phil. 524 (1951)', 'h': 'A man who staged and circulated a photograph of himself apparently hanging from a tree, with a “suicide note” vilifying the Government, was convicted of inciting to sedition: the publication was a scurrilous libel against the Government that tended to stir people to rebellion.', 'r': 'Scurrilous libels against the Government.'}],
      chk=['scurrilous libels'])
    n(143, 'Acts tending to prevent the meeting of Congress and similar bodies: preventing, by force or fraud, the meeting of Congress, its committees, the Constitutional Commissions or local legislative bodies.', chk=['by force or fraud'])
    n(144, 'Disturbance of proceedings: disturbing the meetings of Congress, its committees, the Constitutional Commissions, or local legislative bodies, or behaving in their presence so as to interrupt proceedings or impair the respect due them.', chk=['interrupt its proceedings'])
    n(145, 'Violation of parliamentary immunity: (1) using force, intimidation, threats or fraud to prevent a member of Congress from attending its meetings, expressing opinions or voting; or (2) a public officer who, while Congress is in session, arrests or searches a member, unless the member committed a crime punishable by a penalty higher than prision mayor.',
      t=['Compare the Constitution (Art. VI, Sec. 11): privilege from arrest only for offenses punishable by not more than six years’ imprisonment, while Congress is in session. The constitutional rule prevails where they differ.'],
      d=[{'n': 'People v. Jalosjos', 'c': 'G.R. Nos. 132875-76, February 3, 2000', 'h': 'A congressman convicted of statutory rape could not attend sessions while serving sentence; the privilege from arrest does not cover offenses punishable by more than six years, and election does not free a convicted prisoner.', 'r': 'Limits of parliamentary immunity.'}],
      chk=['higher than prision mayor'])
    n(146, 'Illegal assemblies (as amended by RA 12): (1) a meeting attended by armed persons for the purpose of committing any crime under the Code; or (2) a meeting where the audience is incited to treason, rebellion, sedition or assault upon a person in authority. Organizers and leaders, and persons present, are punished; a person present with an unlicensed firearm is presumed to share the purpose and is treated as a leader.',
      t=['In the first form, the persons attending must be armed; in the second, they need not be.', '“Meeting” includes a gathering or group, fixed or moving.'],
      chk=['unlicensed firearm', 'fixed place or moving'])
    n(147, 'Illegal associations: associations organized totally or partially to commit crimes under the Code, or for purposes contrary to public morals. Founders, directors and presidents are punished; members, less severely.',
      t=['The association need not hold a meeting; the crime is in its organization and purpose. Compare Art. 146 (meetings).'], chk=['contrary to public morals'])
    n(148, 'Direct assault, two forms: (1) without a public uprising, using force or intimidation to attain any purpose of rebellion or sedition; (2) without a public uprising, attacking, employing force against, or seriously intimidating or resisting a person in authority or his agent while engaged in the performance of official duties, or on occasion of such performance. Qualified when committed with a weapon, by a public officer, or by laying hands on a person in authority.',
      k=['Second form: (a) attack, force, serious intimidation or serious resistance; (b) against a person in authority or his agent; (c) while engaged in the performance of duty or on occasion of it; (d) the offender knows the victim’s character; (e) no public uprising.'],
      t=['Force against an agent of a person in authority must be serious; against a person in authority, any laying of hands suffices to qualify.', 'Direct assault may be complexed with the resulting homicide, murder or physical injuries (Art. 48).', 'The victim must be performing official duties at the time, or attacked because of them; an attack for purely personal reasons is not direct assault.'],
      chk=['without a public uprising', 'person in authority'])
    n(149, 'Indirect assault: using force or intimidation upon any person who comes to the aid of a person in authority or his agent who is the victim of direct assault.',
      t=['There must be a direct assault first; the victim of indirect assault is the person who comes to help.', 'A private person who comes to the aid of a person in authority becomes an agent of a person in authority (Art. 152, as amended), so an attack on him may itself be direct assault.'],
      chk=['coming to the aid of the authorities'])
    n(150, 'Disobedience to summons of Congress, its committees or the Constitutional Commissions: refusing without legal excuse to obey a summons, to be sworn, to answer a legal inquiry, or to produce documents; or restraining another from attending or testifying.',
      t=['The legislative body may also cite the witness in contempt under its own inherent power.'], chk=['without legal excuse'])
    n(151, 'Resistance and serious disobedience to a person in authority or his agent in the performance of duty; a lighter penalty for disobedience that is not serious.',
      k=['A person in authority or agent is performing duty and gives a lawful order.', 'The offender resists or seriously disobeys.', 'The act does not amount to direct assault (Art. 148) or indirect assault.'],
      t=['Direct assault: the offender attacks or employs force; resistance: the offender merely resists or disobeys. Serious resistance with force against an agent may be direct assault.'], chk=['resist or seriously disobey'])
    n(152, 'Who are persons in authority and their agents. Persons in authority: those directly vested with jurisdiction, individually or as members of a court, board or commission; barangay captains and chairpersons; and, for Arts. 148 and 151, teachers, professors and persons charged with the supervision of public or duly recognized private schools, and lawyers in the actual performance of their professional duties or on occasion of it. Agents: those charged with maintaining public order and protecting life and property (barangay councilmen, barrio policemen, barangay leaders), and any person who comes to the aid of persons in authority.',
      t=['Teachers and lawyers are persons in authority only for direct assault and resistance (Arts. 148 and 151), and lawyers only while performing their duties or on occasion of them.', 'BP 873 (1985) added lawyers and those who come to the aid of persons in authority.'],
      chk=['teachers', 'lawyers in the actual performance'])
    n(153, 'Tumults and disturbances of public order: causing serious disturbance in a public place or office; interrupting or disturbing performances, functions or gatherings; outcry tending to incite rebellion or sedition; displaying placards or emblems that provoke a disturbance; and burying with pomp a person legally executed. Heavier if “tumultuous” — caused by more than three armed persons or persons provided with means of violence.',
      t=['RA 10951’s text reads “more three (3) persons” — the word “than” is missing; the 1930 text reads “more than three persons”.'],
      chk=['armed or provided with means of violence'])
    n(154, 'Unlawful use of means of publication and unlawful utterances: publishing false news that may endanger public order or damage the State’s interest or credit; encouraging disobedience to the law or authorities, or praising or justifying crimes, by speech or publication; maliciously publishing official resolutions or documents without authority; and printing or publishing anonymous material.',
      t=['For false news, the publication must be of news “as news” and may endanger public order or cause damage to the State; online publication is covered by RA 10175 (one degree higher).'],
      chk=['false news', 'without proper authority'])
    n(155, 'Alarms and scandals (as amended by RA 11926): discharging rockets, firecrackers or other explosives in a town or public place calculated to cause alarm or danger; instigating a charivari or disorderly meeting; disturbing the public peace at night; or causing disturbance or scandal in public places while intoxicated or otherwise.',
      t=['Discharging a firearm is no longer under Art. 155: RA 11926 (2022) moved wilful and indiscriminate discharge of firearms to Art. 254(b), with a heavier penalty.'],
      chk=['rocket, firecracker', 'charivari'])
    n(156, 'Delivering prisoners from jail: removing a person confined in a jail or penal establishment, or helping him escape, by violence, intimidation or bribery (lighter if by other means). If the offender is a public officer with custody of the prisoner, the crime is infidelity in the custody of prisoners (Arts. 223-224).',
      t=['The prisoner may be a detention prisoner or a convict; the offender is usually an outsider.'], chk=['violence, intimidation, or bribery'])
    n(157, 'Evasion of service of sentence: a convict serving a sentence by final judgment who escapes; heavier if by unlawful entry, breaking doors, windows, gates, walls, roofs or floors, using picklocks, false keys, deceit, violence or intimidation, or connivance with other convicts or employees.',
      t=['Applies only to convicts by final judgment; a detention prisoner who escapes does not commit this crime.', 'Destierro violated by entering the prohibited area is evasion of sentence (People v. Abilong, 1948).'],
      chk=['by reason of final judgment'])
    n(158, 'Evasion on the occasion of disorders, conflagrations, earthquakes, explosions, similar catastrophes, or a mutiny in which he took no part: a convict who leaves the institution and fails to give himself up within 48 hours after the President announces the passing of the calamity suffers an increase of one-fifth of the time remaining; one who returns gets a deduction of one-fifth.',
      t=['Compare Art. 98 as amended by RA 10592 for the loyalty allowance (one-fifth deduction; two-fifths if he stays).'], chk=['one-fifth'])
    n(159, 'Violation of conditional pardon: a convict who violates any condition of a conditional pardon. If the remitted penalty exceeds six years, he serves the unexpired portion of the original sentence.',
      t=['The President may also simply revoke the pardon and recommit the convict (Sec. 64(i), Revised Administrative Code) without a criminal prosecution; the two remedies are distinct.'], chk=['conditional pardon'])
    n(160, 'Quasi-recidivism: a person who commits a felony after conviction by final judgment, before beginning to serve or while serving the sentence, suffers the maximum period of the penalty for the new felony. A quasi-recidivist may be pardoned at 70 if he has served his sentence, unless he is a habitual criminal or otherwise unworthy.',
      t=['It is a special aggravating circumstance: it cannot be offset by ordinary mitigating circumstances.', 'The first offense may be under a special law; the new offense must be a felony under the Code.'],
      chk=['maximum period of the penalty prescribed by law for the new felony'])
